export function roleLabel(role: "admin" | "member" | "unknown") {
  switch (role) {
    case "admin":
      return "Admin";
    case "member":
      return "Member";
    default:
      return "Unknown";
  }
}

edits.newText:
export function roleLabel(role: "admin" | "member" | "unknown") {
  switch (role) {
    case "admin":
      return "Admin";
    case "member":
      return "Member";
    default:
      return "Guest";
  }
}
